def solve(expr):
    def operate(op, b, a):
        if op == '+':
            return a + b
        if op == '-':
            return a - b
        if op == '*':
            return a * b
        if op == '/':
            return a // b

    def precedence(op):
        if op in ('+', '-'):
            return 1
        if op in ('*', '/'):
            return 2
        return 0

    def eval_expr(tokens):
        def apply_ops(ops, vals):
            op = ops.pop()
            b = vals.pop()
            a = vals.pop()
            vals.append(operate(op, b, a))

        nums = []
        ops = []
        i = 0
        while i < len(tokens):
            if tokens[i] == ' ':
                i += 1
                continue
            elif tokens[i] in ('+', '-', '*', '/'):
                while (ops and precedence(ops[-1]) >= precedence(tokens[i])):
                    apply_ops(ops, nums)
                ops.append(tokens[i])
            elif tokens[i] == '(':
                ops.append(tokens[i])
            elif tokens[i] == ')':
                while ops[-1] != '(':
                    apply_ops(ops, nums)
                ops.pop()  # pop '('
            else:  # number
                j = i
                while i < len(tokens) and tokens[i].isdigit():
                    i += 1
                nums.append(int(tokens[j:i]))
                i -= 1
            i += 1

        while ops:
            apply_ops(ops, nums)

        return nums[0]

    # Remove spaces from input expression
    expr = expr.replace(" ", "")
    return eval_expr(expr)

# Example usage:
# print(solve("3+2*2"))
# print(solve("3/2"))
# print(solve(" 3+5 / 2 "))
